import { middleware } from "supertokens-node/framework/koa";
import { SuperTokensConfig } from "./config.ts";
import { verifySession } from "supertokens-node/recipe/session/framework/koa";
import { SessionContext } from "supertokens-node/framework/koa";
import { PrismaClient } from "./prisma/generated/prisma/client.js";
import { withAccelerate } from "@prisma/extension-accelerate";
import { PassThrough } from "stream";
import Koa from "koa";
import http from "node:http";
import cors from "@koa/cors";
import supertokens from "supertokens-node";
import KoaRouter from "koa-router";
import bodyParser from "koa-bodyparser";

const prisma = new PrismaClient({
	accelerateUrl: process.env.DATABASE_URL,
}).$extends(withAccelerate());

const app = new Koa();
const router = new KoaRouter();
const server = http.createServer(app.callback());

//make Koa trust Render's reverse proxy and allow secure cookies
app.proxy = true;

//initialize supertokens
supertokens.init(SuperTokensConfig);

app.use(
	cors({
		origin: process.env.VITE_APP_WEBSITE_URL,
		allowHeaders: ["content-type", ...supertokens.getAllCORSHeaders()],
		credentials: true,
	}),
);

// This exposes all the APIs from SuperTokens to the client.
app.use(middleware());

// body parser for koa,
app.use(bodyParser());

//setup SSE notification stream
const userConnections = new Map();

//ping server
router.get("/api/ping", async (ctx) => {
	ctx.body = "Server ping";
});

// 📡 The SSE Stream Endpoint
router.get("/api/events/stream", async (ctx) => {
	const userId = ctx.query.userId;

	if (!userId) {
		ctx.status = 401;
		ctx.body = "Unauthorized";
		return;
	}

	ctx.set({
		"Content-Type": "text/event-stream",
		"Cache-Control": "no-cache",
		"X-Accel-Buffering": "no",
		Connection: "keep-alive",
	});

	const stream = new PassThrough();
	ctx.body = stream;

	//DISCONNECTION CATCH-UP (Filtered by User ID)
	const lastEventId = parseInt(ctx.headers["last-event-id"] as string);

	if (lastEventId) {
		try {
			// Find only this user's events that happened after they disconnected
			const missedEvents = await prisma.userNotificationEvent.findFirst({
				where: {
					userId: userId as string,
					id: { gt: lastEventId },
				},
				orderBy: { id: "asc" },
			});

			if (missedEvents) {
				ctx.body = `id: ${missedEvents.id}\ndata: ${JSON.stringify(missedEvents.type)}\n\n`;
			}
		} catch (err) {
			console.error(`Failed catching up user ${userId}:`, err);
		}
	}

	// Track this active user connection
	if (!userConnections.has(userId)) {
		userConnections.set(userId, stream);
	}

	// Clean up when this specific connection closes
	ctx.req.on("close", () => {
		stream.end();
		userConnections.delete(userId);
	});
});

// Call this when a server event takes place for a specific user
async function sendEventToUser(userEmail: string) {
	try {
		// Save the targeted event to the Database
		const savedEvent = await prisma.userNotificationEvent.create({
			data: {
				userId: userEmail,
				type: "update-notification",
			},
		});

		if (!savedEvent) {
			return;
		}
		// If the user is currently online, push it live instantly
		if (userConnections.has(userEmail)) {
			const formattedSSE = `id: test\n data: ${JSON.stringify("test")}\n\n`;
			console.log(`Sending event to user: ${userEmail}`);

			userConnections.get(userEmail).write(formattedSSE);
		}
	} catch (err) {
		console.error(`Failed to handle user event for ${userEmail}:`, err);
	}
}

// An example API that requires session verification
router.get("/sessioninfo", verifySession(), (ctx: SessionContext) => {
	const userId = ctx.session!.getUserId();
	const sessionHandle = ctx.session!.getHandle();
	const accessTokenPayload = ctx.session?.getAccessTokenPayload();
	ctx.body = JSON.stringify(
		{ userId, sessionHandle, accessTokenPayload },
		null,
		4,
	);
});

// This API is used by the frontend to get the email of the logged in user to use as id.
router.get("/useremailasid", verifySession(), async (ctx: SessionContext) => {
	const userId = ctx.session!.getUserId();
	let userEmailId = await supertokens.getUser(userId);
	const findUser = await prisma.user.findUnique({
		where: {
			email: userEmailId?.emails[0],
		},
	});
	if (findUser) {
		ctx.body = userEmailId?.emails[0];
		return;
	}
	try {
		const newUser = await prisma.user.create({
			data: {
				email: userEmailId?.emails[0] as string,
				watchlist: [],
				featuredNetworks: [],
				notifications: [],
			},
		});
		if (newUser) {
			ctx.body = userEmailId?.emails[0];
		}
	} catch (error: unknown) {
		ctx.body = { message: `Something went wrong: ${error}` };
	}
});

router.get("/getuserdata", verifySession(), async (ctx: SessionContext) => {
	const userEmail = ctx.query.email as string;
	try {
		const userData = await prisma.user.findUnique({
			where: {
				email: userEmail,
			},
			select: {
				watchlist: true,
				featuredNetworks: true,
				notifications: true,
			},
		});
		ctx.body = userData;
	} catch (error: unknown) {
		ctx.body = { message: `Something went wrong: ${error}` };
	}
});

// router.get("/deleteshows", async (ctx: SessionContext) => {
const deleteShowsData = async () => {
	try {
		const result = await prisma.series.deleteMany({});
		if (result) {
			console.log("Shows deleted successfully.");
		} else {
			console.log(`Something went wrong: ${result}`);
		}
	} catch (error: unknown) {
		console.log(`Something went wrong: ${error}`);
	}
};

//Get Show data from TV Maze API //375
const populateShowsData = async () => {
	let showWithFixedLinksKey: Array<any> = [];
	try {
		for (let i = 0; i < 375; i++) {
			const tvmazeResponse = await fetch(
				`https://api.tvmaze.com/shows?page=${i}`,
			);
			if (!tvmazeResponse.ok) {
				throw new Error(`HTTP error! status: ${tvmazeResponse.status}`);
			}
			let shows = await tvmazeResponse.json();
			if (shows.length !== 0) {
				shows.map((show: any) => {
					const {
						_links,
						id,
						name,
						language,
						genres,
						status,
						runtime,
						premiered,
						rating,
						weight,
						network,
						webChannel,
						image,
						summary,
					} = show;
					let newShow = {
						links: _links,
						tvMazeId: id,
						name,
						language,
						genres,
						status,
						runtime,
						premiered,
						rating,
						weight,
						network,
						webChannel,
						image,
						summary,
					};
					if (typeof show.type === "string") {
						showWithFixedLinksKey.push(newShow);
					}
				});
				const result =
					shows.length > 0
						? await prisma.series.createMany({
								data: [...showWithFixedLinksKey],
							})
						: null;
				if (result) {
					console.log(`Shows added successfully.`);
					// Reset the array for the next iteration
					showWithFixedLinksKey = [];
				} else {
					console.log(`Something went wrong: ${result}`);
				}
			} else {
				return;
			}
		}
	} catch (error: unknown) {
		console.log(`Something went wrong with populating shows: ${error}`);
	}
};

// check for updated shows and update user notifications
const checkForShowsUpdate = async () => {
	try {
		//get daily updated shows
		const rawUpdatedShows = await fetch(
			" https://api.tvmaze.com/updates/shows?since=day",
			{ method: "GET" },
		);
		if (rawUpdatedShows.ok) {
			let updatedShows = Object.keys(
				await rawUpdatedShows.json(),
			) as unknown as Array<number>;
			updatedShows = updatedShows.map((showId) =>
				parseInt(showId as unknown as string),
			);
			if (updatedShows.length == 0) {
				return;
			}
			// get users with shows in their watchlist that have been updated
			const userData = await prisma.user.findMany({
				where: {
					watchlist: { hasSome: updatedShows },
				},
				select: { notifications: true, watchlist: true, email: true },
			});

			if (userData.length == 0) {
				return;
			}
			for (const user of userData) {
				// Keep a local copy of notifications that updates during the inner loop
				let currentNotifications = [...(user.notifications as Array<any>)];

				for (const updatedShow of updatedShows) {
					if (user.watchlist.includes(updatedShow)) {
						const rawUpdatedShowData = await fetch(
							`https://api.tvmaze.com/shows/${updatedShow}`,
						);
						// Local variable so it never leaks across loops
						const updatedShowData = await rawUpdatedShowData.json();

						// Find existing notifications in our locally updating list
						const existingNotification = currentNotifications.find(
							(n: any) => n.showId === updatedShow,
						);

						let newNotification: any = null;

						// Process logic
						if (
							updatedShowData?._links?.nextepisode?.name === "TBA" &&
							!existingNotification?.message?.includes("concluded")
						) {
							newNotification = {
								message: `<b><i>${updatedShowData.name}</i></b>'s season has been concluded`,
								readStatus: false,
								showId: updatedShow,
								previousEpisode:
									updatedShowData?._links?.previousepisode?.name || "N/A",
								status: updatedShowData.status,
							};
						} else if (
							existingNotification?.previousEpisode !==
							updatedShowData?._links?.previousepisode?.name
						) {
							newNotification = {
								message: `<b><i>${updatedShowData.name}</i></b> has a new episode`,
								previousEpisode:
									updatedShowData?._links?.previousepisode?.name || "N/A",
								status: updatedShowData.status,
								readStatus: false,
								showId: updatedShow,
							};
						} else if (
							updatedShowData.status === "Ended" &&
							existingNotification?.status !== "Ended"
						) {
							newNotification = {
								message: `<b><i>${updatedShowData.name}</i></b> has reached the series finale`,
								readStatus: false,
								showId: updatedShow,
								previousEpisode:
									updatedShowData?._links?.previousepisode?.name || "N/A",
								status: updatedShowData.status,
							};
						}

						// 3. If a new notification was built, prepend it to our local array copy
						if (newNotification) {
							currentNotifications = [newNotification, ...currentNotifications];
						}
					}
				}

				//  Update the database exactly ONCE per user with all cumulative new notifications
				if (
					currentNotifications.length !==
					(user!.notifications! as Array<any>).length
				) {
					await prisma.user.update({
						data: {
							notifications: currentNotifications,
						},
						where: { email: user.email },
					});
				}

				// 5. Safely trigger the event after DB persists
				sendEventToUser(user.email);
			}
		}
	} catch (error: unknown) {
		console.log({ error: `Something went wrong: ${error}` });
	}
};

//cron job to update user notifications every 24 hours
router.get("/api/update-notifications", async (ctx) => {
	await checkForShowsUpdate();
	ctx.body = "Notification cron job ran";
});

// cron job to update show data once per week
router.get("/api/update-shows", async (ctx) => {
	ctx.body = "Shows data cron job initiated";
	await deleteShowsData();
	await populateShowsData();
	ctx.body = "Shows data cron job ran";
});

