// format search/filter results
const formatResults = (dataToFormat: any, sortOrder: string) => {
	let networkResults: Array<any> = [];
	let singularNetworkResults: any = {};
	let results: Array<any> = [];
	dataToFormat.map((show: any) => {
		if (
			show.webChannel &&
			show.webChannel.name &&
			!networkResults.includes(show.webChannel.name)
		) {
			networkResults = [...networkResults, show.webChannel.name];
		}
		if (
			show.network &&
			show.network.name &&
			!networkResults.includes(show.network.name)
		) {
			networkResults = [...networkResults, show.network.name];
		}
	});

	if (sortOrder === "asc" || !sortOrder) {
		networkResults.sort((a, b) =>
			a.localeCompare(b, "en", { sensitivity: "base" }),
		);
	} else if (sortOrder === "desc") {
		networkResults.sort((a, b) =>
			b.localeCompare(a, "en", { sensitivity: "base" }),
		);
	}
	for (let i = 0; i < networkResults.length; i++) {
		singularNetworkResults = {
			network: {
				name: networkResults[i],
				logo: `https://jaruba.github.io/channel-logos/export/transparent-white${networkLogos[networkResults[i].toLowerCase()]}`,
			},
			shows: [],
		};
		dataToFormat.map((show: any) => {
			if (
				(show.network && show.network.name === networkResults[i]) ||
				(show.webChannel && show.webChannel.name === networkResults[i])
			) {
				singularNetworkResults.shows = [
					...singularNetworkResults.shows,
					{
						name: show.name,
						summary: show.summary,
						image: show.image,
						rating: show.rating,
						runtime: show.runtime,
						language: show.language,
						genres: show.genres,
						tvMazeId: show.tvMazeId,
						premiered: show.premiered,
						status: show.status,
						links: show.links,
					},
				];
			}
		});
		results = [...results, singularNetworkResults];
		singularNetworkResults = {};
	}
	return results.flat();
};

// initial show populate
router.get("/getshowsbynetwork", async (ctx: SessionContext) => {
	let networksToDisplay: Array<string> = [];
	let i: number = parseInt(ctx.query.limit as string) - 3 || 0;
	let y: number = parseInt(ctx.query.limit as string) || 3;
	let networklist: string = (ctx.query.networklist as string) || "";
	let sortOrder: string = (ctx.query.sortorder as string) || "";
	networksToDisplay =
		networklist === "popular" ? popularNetworksArray : allNetworksArray;
	if (sortOrder === "asc") {
		networksToDisplay = networksToDisplay.reverse();
	} else if (sortOrder === "desc") {
		networksToDisplay = networksToDisplay.sort((a, b) =>
			a.localeCompare(b, "en", { sensitivity: "base" }),
		);
	}
	let showsByNetwork: Array<any> = [];
	let networkLogo: string = "";

	if (y > networksToDisplay.length) {
		y = networksToDisplay.length;
	}

	try {
		for (i; i < y; i++) {
			let getShowsByNetwork: Array<any> = [];
			if (webChannelArray.includes(networksToDisplay[i])) {
				getShowsByNetwork = await prisma.series.findMany({
					where: {
						webChannel: { path: ["name"], equals: networksToDisplay[i] },
					},
					orderBy: { weight: "desc" },
					select: {
						name: true,
						summary: true,
						image: true,
						genres: true,
						runtime: true,
						rating: true,
						premiered: true,
						tvMazeId: true,
						status: true,
						links: true,
					},
				});
			} else {
				getShowsByNetwork = await prisma.series.findMany({
					where: {
						network: { path: ["name"], equals: networksToDisplay[i] },
					},
					orderBy: { weight: "desc" },
					select: {
						name: true,
						summary: true,
						image: true,
						runtime: true,
						rating: true,
						premiered: true,
						tvMazeId: true,
						status: true,
						links: true,
					},
				});
			}

			networkLogo = `https://jaruba.github.io/channel-logos/export/transparent-white${networkLogos[networksToDisplay[i].toLowerCase()]}`;
			showsByNetwork = [
				...showsByNetwork,
				{
					network: { name: networksToDisplay[i], logo: networkLogo },
					shows: [...getShowsByNetwork.flat()],
				},
			];
			ctx.body = showsByNetwork.flat();
		}
		showsByNetwork = [];
	} catch (e: any) {
		console.log(e);
		ctx.body = { warning: "Failed to fetch data. Please try again later." };
	}
});

// get all networks for watchlist page

router.get("/getnetworks", verifySession(), async (ctx: SessionContext) => {
	try {
		const networkArray: any = await prisma.$queryRaw`
            SELECT DISTINCT "webChannel"->>'name' AS "name" 
            FROM "Series" 
            WHERE "webChannel" IS NOT NULL
            UNION
            SELECT DISTINCT "network"->>'name' AS "name" 
            FROM "Series" 
            WHERE "network" IS NOT NULL`;

		let networks: Array<any> = [];
		networkArray.map((networkObj: any) => {
			if (networkObj.name) {
				networks = [...networks, networkObj.name];
			}
		});
		networks = networks.sort((a, b) =>
			a.localeCompare(b, "en", { sensitivity: "base" }),
		);

		if (networks.length === 0) {
			ctx.body = {
				warning: "Failed to fetch networks. Please try again later.",
			};
			return;
		}
		ctx.set("Cache-Control", "public, max-age=36000");
		ctx.body = networks;
	} catch (e: any) {
		console.log(e);
		ctx.body = {
			warning: "Failed to fetch networks. Please try again later.",
		};
	}
});

// get data for filtering
router.get("/getfilterdata", async (ctx: SessionContext) => {
	try {
		const [networkArray, genresArray, languageArray, statusArray]: Array<any> =
			await prisma.$transaction([
				prisma.$queryRaw`
            SELECT DISTINCT "webChannel"->>'name' AS "name" 
            FROM "Series" 
            WHERE "webChannel" IS NOT NULL
            UNION
            SELECT DISTINCT "network"->>'name' AS "name" 
            FROM "Series" 
            WHERE "network" IS NOT NULL`,
				prisma.series.findMany({
					distinct: ["genres"],
					select: { genres: true },
				}),
				prisma.series.findMany({
					distinct: ["language"],
					select: { language: true },
				}),
				prisma.series.findMany({
					distinct: ["status"],
					select: { status: true },
				}),
			]);

		let networks: Array<any> = [];
		let genres: Array<any> = [];
		let languages: Array<any> = [];
		let status: Array<any> = [];

		// process networks
		networkArray.map((networkObj: any) => {
			if (networkObj.name) {
				networks = [...networks, networkObj.name];
			}
		});
		// process genres
		genresArray.map((genreObj: any) => {
			genreObj.genres.map((genre: string) => {
				if (genre && !genres.includes(genre)) {
					genres = [...genres, genre];
				}
			});
		});
		// process languages
		languageArray.map((languageObj: any) => {
			if (languageObj.language && !languages.includes(languageObj.language)) {
				languages = [...languages, languageObj.language];
			}
		});
		// process status
		statusArray.map((statusObj: any) => {
			if (statusObj.status && !status.includes(statusObj.status)) {
				status = [...status, statusObj.status];
			}
		});
		networks = networks.sort((a, b) =>
			a.localeCompare(b, "en", { sensitivity: "base" }),
		);
		genres = genres.sort((a, b) =>
			a.localeCompare(b, "en", { sensitivity: "base" }),
		);
		languages = languages.sort((a, b) =>
			a.localeCompare(b, "en", { sensitivity: "base" }),
		);
		status = status.sort((a, b) =>
			a.localeCompare(b, "en", { sensitivity: "base" }),
		);

		ctx.set("Cache-Control", "public, max-age=36000");
		ctx.body = { networks, genres, languages, status };
	} catch (e: any) {
		console.log(e);
		ctx.body = {
			error: "Failed to fetch filter data. Please try again later.",
		};
	}
});
// search by show name
router.get("/searchshows", async (ctx: SessionContext) => {
	let searchTerm: string = (ctx.query.searchterm as string) || "";
	let sortOrder: string = (ctx.query.sortOrder as string) || "";
	let i: number = parseInt(ctx.query.limit as string) - 3 || 0;
	let y: number = parseInt(ctx.query.limit as string) || 3;
	try {
		const searchRawResults = await prisma.series.findMany({
			where: {
				name: { contains: searchTerm, mode: "insensitive" },
			},
			orderBy: { weight: "desc" },
			select: {
				name: true,
				summary: true,
				image: true,
				network: true,
				genres: true,
				webChannel: true,
				runtime: true,
				rating: true,
				premiered: true,
				tvMazeId: true,
				status: true,
				links: true,
			},
		});
		const searchResults = formatResults(searchRawResults, sortOrder);

		const results: any[] = [];
		if (y > searchResults.length) {
			y = searchResults.length;
		}
		for (i; i < y; i++) {
			results.push(searchResults[i]);
		}
		ctx.body = results;
	} catch (e: any) {
		console.log(e);
		const match = e.message.match(/\{.*\}/s);
		if (match) {
			const parsed = JSON.parse(match[0]);
			const code = parsed?.body?.code;
			if (code === "P6009") {
				ctx.body = {
					warning: "Too many results. Please refine your criteria.",
				};
			} else {
				ctx.body = { warning: "Failed to fetch data. Please try again later." };
			}
		}
		//if no match
		ctx.body = { warning: "Failed to fetch data. Please try again later." };
	}
});

//get results for filters
router.get("/getshowsbyfilters", async (ctx: SessionContext) => {
	let i: number = parseInt(ctx.query.limit as string) - 3 || 0;
	let y: number = parseInt(ctx.query.limit as string) || 3;
	let sortOrder: string = (ctx.query.sortOrder as string) || "";
	let networks: any =
		(ctx.query.networks as string).length > 0
			? (ctx.query.networks as string).split(",")
			: [];
	let genres: any =
		(ctx.query.genres as string).length > 0
			? (ctx.query.genres as string).split(",")
			: [];
	let languages: any =
		(ctx.query.languages as string).length > 0
			? (ctx.query.languages as string).split(",")
			: [];
	let status: any =
		(ctx.query.status as string).length > 0
			? (ctx.query.status as string).split(",")
			: [];
	let rating: any =
		(ctx.query.rating as string).length > 0
			? (ctx.query.rating as string).split(",")
			: [];
	let unratedShows: boolean =
		ctx.query.unratedShows?.toString() === "true" ? true : false;
	let runtime: any =
		(ctx.query.runtime as string).length > 0
			? (ctx.query.runtime as string).split(",")
			: [];
	let filterParams: {
		networks: Array<string>;
		genres: Array<string>;
		languages: Array<string>;
		status: Array<string>;
		rating: Array<string>;
		unratedShows: boolean;
		runtime: Array<string>;
	} = {
		networks: [],
		genres: [],
		languages: [],
		status: [],
		rating: [],
		unratedShows: false,
		runtime: [],
	};
	filterParams.genres = genres;
	filterParams.networks = networks;
	filterParams.languages = languages;
	filterParams.status = status;
	filterParams.rating = rating;
	filterParams.runtime = runtime;
	filterParams.unratedShows = unratedShows;

	const filterArgument: any = [];
	const filterArgumentOR: any = [];
	const filterArgumentAND: any = [];
	filterParams.genres.length > 0
		? filterArgument.push({ genres: { hasSome: filterParams.genres } })
		: null;
	filterParams.networks.length > 0
		? filterParams.networks.map((network: string) => {
				filterArgumentOR.push(
					{ webChannel: { path: ["name"], equals: network } },
					{ network: { path: ["name"], equals: network } },
				);
			})
		: null;
	filterParams.languages.length > 0
		? filterArgumentOR.push({ language: { in: filterParams.languages } })
		: null;
	filterParams.status.length > 0
		? filterArgument.push({ status: { in: filterParams.status } })
		: null;
	filterParams.runtime[0] === "0"
		? null
		: filterArgumentAND.push({
				runtime: { gte: parseFloat(filterParams.runtime[0]) },
			});
	filterParams.runtime[1] === "120"
		? null
		: filterArgumentAND.push({
				runtime: { lte: parseFloat(filterParams.runtime[0]) },
			});
	filterParams.unratedShows
		? null
		: filterArgumentAND.push({ rating: { path: ["average"], not: null } });
	filterParams.rating[0] === "0"
		? null
		: filterArgumentAND.push({
				rating: {
					path: ["average"],
					gte: parseFloat(filterParams.rating[0]),
				},
			});
	filterParams.rating[1] === "10"
		? null
		: filterArgumentAND.push({
				rating: {
					path: ["average"],
					lte: parseFloat(filterParams.rating[1]),
				},
			});

	try {
		const RawFilteredResults = await prisma.series.findMany({
			where: {
				...Object.assign({}, ...filterArgument, {
					AND: [...filterArgumentAND, { OR: [...filterArgumentOR] }],
				}),
			},
			select: {
				name: true,
				network: true,
				webChannel: true,
				summary: true,
				image: true,
				runtime: true,
				rating: true,
				premiered: true,
				status: true,
				tvMazeId: true,
				genres: true,
				language: true,
				links: true,
			},
			orderBy: {
				weight: "desc",
			},
		});
		RawFilteredResults.map((show: any) => {
			if (
				networks &&
				!networks.includes(show.network?.name) &&
				!genres.some((genre: string) => genres.includes(genre)) &&
				!languages.includes(show.language) &&
				!status.includes(show.status)
			) {
				delete show.network?.name;
			}
			if (
				networks &&
				!networks.includes(show.webChannel?.name) &&
				!genres.some((genre: string) => genres.includes(genre)) &&
				!languages.includes(show.language) &&
				!status.includes(show.status)
			) {
				delete show.webChannel?.name;
			}
		});
		const filteredResults = formatResults(RawFilteredResults, sortOrder);
		const results: any[] = [];
		if (y > filteredResults.length) {
			y = filteredResults.length;
		}
		for (i; i < y; i++) {
			results.push(filteredResults[i]);
		}

		ctx.body = results;
	} catch (e: any) {
		console.log(e);
		const match = e.message.match(/\{.*\}/s);
		if (match) {
			const parsed = JSON.parse(match[0]);
			const code = parsed?.body?.code;
			if (code === "P6009") {
				ctx.body = {
					warning: "Too many results. Please refine your criteria.",
				};
			} else {
				ctx.body = {
					warning: "Failed to fetch data. Please try again later.",
				};
			}
		}
		//if no match
		ctx.body = { warning: "Failed to fetch data. Please try again later." };
	}
});

// get user watchlist shows
router.get(
	"/getwatchlistshows",
	verifySession(),
	async (ctx: SessionContext) => {
		let shows: number[] =
			(ctx.query.shows as string).length > 0
				? (ctx.query.shows as string).split(",").map((s) => parseInt(s))
				: [];

		try {
			const rawWatchlistResults = await prisma.series.findMany({
				where: {
					tvMazeId: { in: shows },
				},
				select: {
					name: true,
					network: true,
					webChannel: true,
					summary: true,
					image: true,
					runtime: true,
					rating: true,
					premiered: true,
					status: true,
					tvMazeId: true,
					genres: true,
					language: true,
				},
				orderBy: {
					weight: "desc",
				},
			});
			const watchlistResults = formatResults(rawWatchlistResults, "asc");
			ctx.body = watchlistResults;
		} catch (e: any) {
			ctx.body = {
				warning: "Failed to fetch watchlist shows. Please try again later.",
			};
			console.log(e);
		}
	},
);

// get user notifications
router.get(
	"/getnotifications",
	verifySession(),
	async (ctx: SessionContext) => {
		const userEmail = ctx.query.userEmail as string;
		try {
			const getNotifications = await prisma.user.findUnique({
				where: { email: userEmail },
				select: { notifications: true },
			});
			if (!getNotifications) {
				ctx.body = {
					error: "Failed to fetch notifications. Please try again later.",
				};
				return;
			}
			ctx.body = getNotifications.notifications;
		} catch (e: any) {
			console.log(e);
			ctx.body = {
				error: "Failed to fetch notifications. Please try again later.",
			};
		}
	},
);

// add show to watchlist
router.post("/addtowatchlist", verifySession(), async (ctx: SessionContext) => {
	const { showId, showName, previousEpisode, status, userEmail } = ctx.request
		.body as {
		showId: number;
		showName: string;
		previousEpisode: string;
		status: string;
		userEmail: string;
	};

	try {
		const getNotifications = await prisma.user.findUnique({
			where: { email: userEmail },
			select: { notifications: true },
		});

		const updateNotification = [
			{
				message: `<b><i>${showName}</i></b> has been added to your watchlist`,
				previousEpisode: previousEpisode,
				status: status,
				showId: showId,
				readStatus: false,
			},
			...(getNotifications?.notifications as Array<Object>),
		];
		const addShow = await prisma.user.update({
			data: {
				watchlist: { push: showId },
				notifications: updateNotification,
			},
			where: { email: userEmail },
			select: { watchlist: true, notifications: true },
		});
		if (!addShow) {
			ctx.body = {
				error: "Failed to add show to watchlist. Please try again later.",
			};
			return;
		}
		ctx.body = addShow;
	} catch (e: any) {
		console.log(e);
		ctx.body = {
			error: "Failed to add show to watchlist. Please try again later.",
		};
	}
});

// remove show from watchlist
router.delete(
	"/removefromwatchlist",
	verifySession(),
	async (ctx: SessionContext) => {
		const { showId, showName, userEmail } = ctx.request.body as {
			showId: number;
			showName: string;
			userEmail: string;
		};
		try {
			const userData = await prisma.user.findUnique({
				where: { email: userEmail },
				select: { watchlist: true, notifications: true },
			});

			const getNotifications = await prisma.user.findUnique({
				where: { email: userEmail },
				select: { notifications: true },
			});
			if (userData && userData.watchlist) {
				const updatedWatchlist = userData.watchlist.filter(
					(id: number) => id !== showId,
				);
				const updatedNotifications = [
					{
						message: `<b><i>${showName}</i></b> has been removed from your watchlist`,
						showId: showId,
						readStatus: false,
					},
					...(getNotifications?.notifications as Array<Object>),
				];
				const removeShow = await prisma.user.update({
					data: {
						watchlist: updatedWatchlist,
						notifications: updatedNotifications,
					},
					where: { email: userEmail },
					select: { watchlist: true, notifications: true },
				});
				if (!removeShow) {
					ctx.body = {
						error:
							"Failed to remove show from watchlist. Please try again later.",
					};
					return;
				}
				ctx.body = removeShow;
			} else {
				ctx.body = {
					error:
						"Failed to remove show from watchlist. Please try again later.",
				};
			}
		} catch (e: any) {
			console.log(e);
			ctx.body = {
				error: "Failed to remove show from watchlist. Please try again later.",
			};
		}
	},
);

// toggle notification status for a show in watchlist
router.post(
	"/togglenotificationreadstatus",
	verifySession(),
	async (ctx: SessionContext) => {
		const { index, readStatus, userEmail } = ctx.request.body as {
			index: number;
			readStatus: boolean;
			userEmail: string;
		};
		try {
			const getNotification = await prisma.user.findUnique({
				where: { email: userEmail },
				select: { notifications: true },
			});
			if (!getNotification?.notifications || !getNotification) {
				ctx.body = {
					error:
						"User not found or no notifications available. Please try again later.",
				};
			} else {
				if (index !== undefined) {
					getNotification.notifications[index].readStatus = readStatus;
				} else {
					getNotification.notifications = (
						getNotification.notifications as Array<any>
					).map((notification: any) => {
						return { ...notification, readStatus: true };
					});
				}
				const updateNotification = await prisma.user.update({
					data: {
						notifications: getNotification.notifications,
					},
					where: { email: userEmail },
					select: { notifications: true },
				});

				if (!updateNotification) {
					ctx.body = {
						error:
							"Unable to change the read status of the notification. Please try again later.",
					};
				}
				ctx.body = updateNotification;
			}
		} catch (e: any) {
			console.log(e);
			ctx.body = {
				error:
					"Unable to change the read status of the notification. Please try again later.",
			};
		}
	},
);

// add show to featured networks
router.post(
	"/savefeaturednetworks",
	verifySession(),
	async (ctx: SessionContext) => {
		const { networks, userEmail } = ctx.request.body as {
			networks: string[];
			userEmail: string;
		};
		try {
			const editedNetworks = await prisma.user.update({
				data: { featuredNetworks: networks },
				where: { email: userEmail },
				select: { watchlist: true, featuredNetworks: true },
			});
			ctx.body = editedNetworks;
		} catch (e: any) {
			console.log(e);
			ctx.body = {
				error: "Unable to edit featured networks. Please try again later.",
			};
		}
	},
);

